('PT158-S4-Q16','note','09a77bf8-7701-4c66-95eb-47c451b1d341','C','19a93fe6-3350-4f77-a976-f0d00fe3a012','f956dc0aeadd4bc50f71d219f44a6205','02e4226d92ca320a96ecdc9967323ceb',NULL,NULL),
('PT158-S4-Q16','note','09a77bf8-7701-4c66-95eb-47c451b1d341','D','fd1c9e7d-99fc-4f83-827c-20a7fb83adf0','c9794793e70c42eedb5f2a256a60bc7f','2734bf535c20a1be09a50061f66a9ee8',NULL,NULL),
('PT158-S4-Q16','note','09a77bf8-7701-4c66-95eb-47c451b1d341','E','b8b4ba08-9ab2-461d-861d-80c2b05eb876','5a35f34ef1115a8aa10a050bb9c78c18','cd81e9f6fff9fb947545fc5c5d4eac0b',NULL,NULL)), actual as (
 select 'step'::text kind, explanation_id::text eid, position::text slot,id::text rid,md5(body) body_md5,coalesce(label,'') label from lr_explanation_steps
 union all select 'note',explanation_id::text,letter::text,id::text,md5(body),null::text from lr_explanation_choice_notes
), checked as (
 select e.*,count(a.rid)::integer matches,
 count(a.rid) filter(where a.body_md5=e.new_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.new_label))::integer final_matches,
 count(a.rid) filter(where a.body_md5=e.old_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.old_label))::integer old_matches,
 jsonb_agg(jsonb_build_object('rid',a.rid,'md5',a.body_md5,'label',a.label)) filter(where a.rid is not null) actual
 from expected e left join actual a on a.kind=e.kind and a.eid=e.eid and a.slot=e.slot
 group by e.qid,e.kind,e.eid,e.slot,e.rid,e.new_md5,e.old_md5,e.new_label,e.old_label
), extras as (
 select a.kind,a.eid,a.slot,count(*) count from actual a
 where a.eid in (select distinct eid from expected) and not exists(select 1 from expected e where e.eid=a.eid and e.kind=a.kind and e.slot=a.slot)
 group by a.kind,a.eid,a.slot
)
select jsonb_build_object('batch','e23','expected_rows',(select count(*) from checked),'final_rows',(select count(*) from checked where matches=1 and final_matches=1),'old_rows',(select count(*) from checked where matches=1 and old_matches=1),'missing',(select count(*) from checked where matches=0),'duplicate_slots',(select count(*) from checked where matches>1),'mismatches',coalesce((select jsonb_agg(jsonb_build_object('qid',qid,'kind',kind,'slot',slot,'expected_id',rid,'expected_md5',new_md5,'matches',matches,'old_matches',old_matches,'actual',actual)) from checked where matches<>1 or final_matches<>1),'[]'::jsonb),'extra_slots',coalesce((select jsonb_agg(to_jsonb(extras)) from extras),'[]'::jsonb)) audit;
